 "content": "def transform(grid):
    """Mirror the 4-colored figure downward across its lower edge; erase 6."""
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    if not cells:
        return out
    bottom = max(r for r, _ in cells)
    for r, row in enumerate(out):
        for c, value in enumerate(row):
            if value == 6:
                out[r][c] = 0
    for r, c in cells:
        rr = 2 * bottom + 1 - r
        if 0 <= rr < len(out):
            out[rr][c] = 4
    return out
